class Solution(object):
    def prefixConnected(self, words, k):
        """
        :type words: List[str]
        :type k: int
        :rtype: int
        """
        # pre-process
        from collections import defaultdict
        dicts = defaultdict(int)

        # process
        for word in words:
            if len(word) >= k:
                key = word[:k]
                dicts[key] += 1

        # post-process
        ans = 0
        for key in dicts:
            if dicts[key] > 1:
                ans += 1
        return ans


